(386124, 33107, 8522, '<td valign="top">Please make sure your image size is larger next time, this is too small! 3</td>', 'Please make sure your image size is larger next time, this is too small! 3', '2003-08-13 05:57:40.000000', NULL, 1),
(386125, 32935, 10832, '<td valign="top">I love this photo.  Although I admit I have been scoring most old house photos between the 3 and 7 range because I think they are cliched, I think that you have managed to convey the emotion of desolation as well (within my defininition of the word).  Dark and raw and ugly and ruined.  I love it.  Thanks.</td>', 'I love this photo.  Although I admit I have been scoring most old house photos between the 3 and 7 range because I think they are cliched, I think that you have managed to convey the emotion of desolation as well (within my defininition of the word).  Dark and raw and ugly and ruined.  I love it.  Thanks.', '2003-08-13 05:58:34.000000', NULL, 1),
(386129, 33026, 8643, '<td valign="top">Dramatic and macabre - beautifully photographed. Great composition, excellent control over focus, crisp foreground, clear backdrop - must be a winner!</td>', 'Dramatic and macabre - beautifully photographed. Great composition, excellent control over focus, crisp foreground, clear backdrop - must be a winner!', '2003-08-13 06:06:20.000000', NULL, 1),
(386130, 33176, 8643, '<td valign="top">This is nearly my top rated pic.  I can''t make up my mind about it - the garish blue is unsettling and knowledge of the history of destruction is also a factor. Well done for being provocative!</td>', 'This is nearly my top rated pic.  I can''t make up my mind about it - the garish blue is unsettling and knowledge of the history of destruction is also a factor. Well done for being provocative!', '2003-08-13 06:06:51.000000', NULL, 1),
(386134, 33245, 4258, '<td valign="top">This portrait was the first which caught my attention - The cheery print in the background adds to the contrast of the expression on his face. Purist of technicals will point that there is glare from the left but that literally pales into insignificance in light of excellence of capture [10]</td>', 'This portrait was the first which caught my attention - The cheery print in the background adds to the contrast of the expression on his face. Purist of technicals will point that there is glare from the left but that literally pales into insignificance in light of excellence of capture [10]', '2003-08-13 06:15:56.000000', NULL, 1),
(386137, 33174, 4258, '<td valign="top">The image is very noisy and the road part looks more like a dark waterbody</td>', 'The image is very noisy and the road part looks more like a dark waterbody', '2003-08-13 06:18:25.000000', NULL, 1),
