INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(386530, 32751, 9690, '<td valign="top">Nice to see you have a subject in the shot (the man).  Good job</td>', 'Nice to see you have a subject in the shot (the man).  Good job', '2003-08-13 12:24:05.000000', NULL, 1),
(386532, 33079, 9690, '<td valign="top">kind of a dull shot... it is flat</td>', 'kind of a dull shot... it is flat', '2003-08-13 12:24:43.000000', NULL, 1),
(386533, 32782, 2978, '<td valign="top">This is pretty cool. Good choice of B&amp;W. The background texture makes the front outstanding. I like the direction of the lines that go in the same way too. Good luck :-)</td>', 'This is pretty cool. Good choice of B&W. The background texture makes the front outstanding. I like the direction of the lines that go in the same way too. Good luck :-)', '2003-08-13 12:25:03.000000', NULL, 1),
(386534, 33086, 9690, '<td valign="top">desolation or desperation???</td>', 'desolation or desperation???', '2003-08-13 12:25:06.000000', NULL, 1),
(386535, 33045, 2890, '<td valign="top">I really like this one. Good shot!</td>', 'I really like this one. Good shot!', '2003-08-13 12:25:48.000000', NULL, 1),
(386537, 33232, 10643, '<td valign="top">I can''t wait to find out where this was taken. The idea of coming across an abandoned paddle steamer in a clearing is just beautiful. I love that there are still things like this to be found in this day and age.</td>', 'I can''t wait to find out where this was taken. The idea of coming across an abandoned paddle steamer in a clearing is just beautiful. I love that there are still things like this to be found in this day and age.', '2003-08-13 12:26:32.000000', NULL, 1),
(386538, 33109, 9690, '<td valign="top">i like the long shadow.  good effect</td>', 'i like the long shadow.  good effect', '2003-08-13 12:26:39.000000', NULL, 1),
(386539, 32396, 8268, '<td valign="top">at the beginin of this challenge, i had a similar idea of this.. after a few days, i realized that is a very clearly desolation.. but there is more desolation in this world than that..    lack of love, indifference, loneliness, ..    i dont know what Im saying you this.. maybe it would be more interesting to see the "cause" of desolation, instead of the results.. i mean to show the history behind of this person, see her face, his history.. his shoes, how talks...</td>', 'at the beginin of this challenge, i had a similar idea of this.. after a few days, i realized that is a very clearly desolation.. but there is more desolation in this world than that..    lack of love, indifference, loneliness, ..    i dont know what Im saying you this.. maybe it would be more interesting to see the "cause" of desolation, instead of the results.. i mean to show the history behind of this person, see her face, his history.. his shoes, how talks...', '2003-08-13 12:27:27.000000', NULL, 1),
(386541, 33140, 9690, '<td valign="top">good shot.  There is a little too much contrast between the window and the room inside, though</td>', 'good shot.  There is a little too much contrast between the window and the room inside, though', '2003-08-13 12:28:19.000000', NULL, 1),
(386542, 32783, 9889, '<td valign="top">Beautiful photo, nice composition and even nice acting! But.. she is acting, isn''t she?  I mean.. the overall look is cool more than desolated. I had to give it just 5.</td>', 'Beautiful photo, nice composition and even nice acting! But.. she is acting, isn''t she?  I mean.. the overall look is cool more than desolated. I had to give it just 5.', '2003-08-13 12:28:28.000000', NULL, 1),
(386543, 33043, 10151, '<td valign="top">I love this shot.  The focus seems to be a bit soft though.</td>', 'I love this shot.  The focus seems to be a bit soft though.', '2003-08-13 12:29:14.000000', NULL, 1),
(386544, 33199, 2978, '<td valign="top">Good shot. This is much beter then many other empty houses in this challenge. I uess because you didnb''t try to capture the whole house but composed it with useful environment. That always works.</td>', 'Good shot. This is much beter then many other empty houses in this challenge. I uess because you didnb''t try to capture the whole house but composed it with useful environment. That always works.', '2003-08-13 12:29:50.000000', NULL, 1),
(386545, 33046, 9690, '<td valign="top">good idea.  It comes off a little flat, though.  There is no focal point... no subject to break up the picture a little</td>', 'good idea.  It comes off a little flat, though.  There is no focal point... no subject to break up the picture a little', '2003-08-13 12:29:54.000000', NULL, 1),
(386546, 32760, 8268, '<td valign="top">nice idea.. but .. too much color, too much grain.. try it in b/w, more contrast.. something more dramatic..</td>', 'nice idea.. but .. too much color, too much grain.. try it in b/w, more contrast.. something more dramatic..', '2003-08-13 12:31:07.000000', NULL, 1),
