(386550, 33026, 9690, '<td valign="top">might have been better if the subject wasnt centered</td>', 'might have been better if the subject wasnt centered', '2003-08-13 12:32:19.000000', NULL, 1),
(386551, 33072, 9690, '<td valign="top">freaky!!!!!</td>', 'freaky!!!!!', '2003-08-13 12:32:45.000000', NULL, 1),
(386553, 32760, 9690, '<td valign="top">good shot... really captures the mood</td>', 'good shot... really captures the mood', '2003-08-13 12:33:58.000000', NULL, 1),
