(386770, 33174, 10414, '<td valign="top">Wow....was the sun really that color??  Beautiful depiction of lonliness! :)</td>', 'Wow....was the sun really that color??  Beautiful depiction of lonliness! :)', '2003-08-13 14:21:20.000000', NULL, 1),
