(386776, 32782, 9436, '<td valign="top">Amazing subject!</td>', 'Amazing subject!', '2003-08-13 14:23:38.000000', NULL, 1),
(386777, 32668, 10414, '<td valign="top">Great shot.....poor little dead thing though! :)  This could have been darkened a bit or maybe been in black and white or sepia, for a more "dark" feel. Wonderful picture though!  :)</td>', 'Great shot.....poor little dead thing though! :)  This could have been darkened a bit or maybe been in black and white or sepia, for a more "dark" feel. Wonderful picture though!  :)', '2003-08-13 14:23:57.000000', NULL, 1),
