(386995, 32407, 10047, '<td valign="top">Good lonely feeling. I might have tried darkening it to see if I got more impact.</td>', 'Good lonely feeling. I might have tried darkening it to see if I got more impact.', '2003-08-13 16:45:19.000000', NULL, 1),
(386998, 33118, 10047, '<td valign="top">Looks like Lake Erie. I would have tried changing to sepia or mono to see if it had a lonelier impact.</td>', 'Looks like Lake Erie. I would have tried changing to sepia or mono to see if it had a lonelier impact.', '2003-08-13 16:47:09.000000', NULL, 1),
(387001, 33237, 9295, '<td valign="top">In this instance, I think centering the still life better would have been more effective.  Interesting use of light to just vaguely suggest the flowers for the most part.</td>', 'In this instance, I think centering the still life better would have been more effective.  Interesting use of light to just vaguely suggest the flowers for the most part.', '2003-08-13 16:48:17.000000', NULL, 1),
