(387009, 32966, 9295, '<td valign="top">Brighten it up so that the facade of the building is more visible and I think this would have been more effective.</td>', 'Brighten it up so that the facade of the building is more visible and I think this would have been more effective.', '2003-08-13 16:52:11.000000', NULL, 1),
(387011, 33086, 6624, '<td valign="top">this is obviously powerful and certainly desolate</td>', 'this is obviously powerful and certainly desolate', '2003-08-13 16:53:52.000000', NULL, 1),
(387015, 32718, 9295, '<td valign="top">I like how the lighting captures the character of the building, particularly the bricks.  I also think the tree branches and pole in the front adds depth to the shot that would otherwise have been lost without it. Nicely done.</td>', 'I like how the lighting captures the character of the building, particularly the bricks.  I also think the tree branches and pole in the front adds depth to the shot that would otherwise have been lost without it. Nicely done.', '2003-08-13 16:55:30.000000', NULL, 1),
(387026, 33186, 6624, '<td valign="top">the stormy sky has motion in an interesting way</td>', 'the stormy sky has motion in an interesting way', '2003-08-13 17:02:39.000000', NULL, 1),
(387027, 32357, 6624, '<td valign="top">the reflected emotion serves the image well</td>', 'the reflected emotion serves the image well', '2003-08-13 17:03:22.000000', NULL, 1),
(387028, 33239, 6624, '<td valign="top">hot to look at even...</td>', 'hot to look at even...', '2003-08-13 17:03:40.000000', NULL, 1),
