(387264, 32819, 10883, '<td valign="top">Good picture, great colours and mood. - 8</td>', 'Good picture, great colours and mood. - 8', '2003-08-13 19:43:20.000000', NULL, 1),
(387265, 33006, 3955, '<td valign="top">nice contrasts, the door and the corner break up the pattern well so the picture has focal points and is not monotonous</td>', 'nice contrasts, the door and the corner break up the pattern well so the picture has focal points and is not monotonous', '2003-08-13 19:43:34.000000', NULL, 1),
(387266, 33245, 772, '<td valign="top">I think this is a particularly good photograph.  Your uncle makes a great subject for a photograph.  I also like the way he is separated from teh bright background and how the details in the ''age'' on his face are still perfectly exposed.  I think that the only possible improvement I can see for this image would be a little bit of catch lighting in his eyes... excellent shot :) = 10</td>', 'I think this is a particularly good photograph.  Your uncle makes a great subject for a photograph.  I also like the way he is separated from teh bright background and how the details in the ''age'' on his face are still perfectly exposed.  I think that the only possible improvement I can see for this image would be a little bit of catch lighting in his eyes... excellent shot :) = 10', '2003-08-13 19:45:01.000000', NULL, 1),
(387267, 32396, 11127, '<td valign="top">Definately conveys the theme.</td>', 'Definately conveys the theme.', '2003-08-13 19:45:10.000000', NULL, 1),
(387268, 32990, 10799, '<td valign="top">Beautiful... I don''t know that I would think of desolate.</td>', 'Beautiful... I don''t know that I would think of desolate.', '2003-08-13 19:47:02.000000', NULL, 1),
(387269, 32390, 3955, '<td valign="top">others might see this as a sign of life in an otherwise desolate place.  cool photo anyway...</td>', 'others might see this as a sign of life in an otherwise desolate place.  cool photo anyway...', '2003-08-13 19:47:25.000000', NULL, 1),
