INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(389972, 33045, 3032, '<td valign="top">Awesome contrast between the warm yellow light on the tree and the cool deepbue to underwatergreen of the sky. The dark profile of the horizon takes the eye across the photo.<br/>The warmth of the presumably death three is also in stromg contrast with the almost desolate landscape.<br/>Excellent.</td>', 'Awesome contrast between the warm yellow light on the tree and the cool deepbue to underwatergreen of the sky. The dark profile of the horizon takes the eye across the photo.The warmth of the presumably death three is also in stromg contrast with the almost desolate landscape.Excellent.', '2003-08-16 21:47:02.000000', NULL, 1),
(389974, 33151, 10414, '<td valign="top">The black and blue in your picture compliment eachother and look wonderful in the overall composition!!   Great shot!!   :)</td>', 'The black and blue in your picture compliment eachother and look wonderful in the overall composition!!   Great shot!!   :)', '2003-08-16 21:49:09.000000', NULL, 1),
(389976, 32990, 3032, '<td valign="top">Good photo.<br/>The cool blue tones and black horizon profile make this pic communicate emptiness cq desolation. The sun trough the sky adds a point of interest. Even the mountains far away add to this in a split second. Somehow, despite the lack of a really strong point of interest, this my favourite for this challenge.</td>', 'Good photo.The cool blue tones and black horizon profile make this pic communicate emptiness cq desolation. The sun trough the sky adds a point of interest. Even the mountains far away add to this in a split second. Somehow, despite the lack of a really strong point of interest, this my favourite for this challenge.', '2003-08-16 21:53:29.000000', NULL, 1),
(389978, 32774, 3032, '<td valign="top">This is a very strong photo.<br/>You''ve got the whales in the front -I guess- and the wind-energy-mills in the background. That is a nice presentation of environmentally friendly making of energy. The background preserves the foregroud in a way. The toning is a bit papyrus colored, a cold blue setting might do better.<br/> <br/>Edit:<br/>LOL Industrial water dump outlets, not whales........<br/><br/><br/><i>Message edited by author 2003-08-23 17:52:35.</i></td>', 'This is a very strong photo.You''ve got the whales in the front -I guess- and the wind-energy-mills in the background. That is a nice presentation of environmentally friendly making of energy. The background preserves the foregroud in a way. The toning is a bit papyrus colored, a cold blue setting might do better. Edit:LOL Industrial water dump outlets, not whales........', '2003-08-16 21:59:19.000000', '2003-08-23 18:52:35.000000', 1),
(389979, 33077, 3032, '<td valign="top">Strong composition communcites the emptyness of the beach very well. Nice toning/exposure, lots of detail. Good photo.</td>', 'Strong composition communcites the emptyness of the beach very well. Nice toning/exposure, lots of detail. Good photo.', '2003-08-16 22:00:50.000000', NULL, 1),
(389980, 33226, 3032, '<td valign="top">This pic would be really great if the horizon was level.<br/>The bird is a great compositional feature and the colors and exposure is very nice. The shoreline draws the eye across the frame ending up at the bird, which keeps the eye inside. Nice job, if only the horizon was at the good and natural perceived angle.</td>', 'This pic would be really great if the horizon was level.The bird is a great compositional feature and the colors and exposure is very nice. The shoreline draws the eye across the frame ending up at the bird, which keeps the eye inside. Nice job, if only the horizon was at the good and natural perceived angle.', '2003-08-16 22:03:43.000000', NULL, 1),
(389988, 32658, 10686, '<td valign="top">I really think this is just too dark, I can''t tell what it is I''m looking at. Sorry</td>', 'I really think this is just too dark, I can''t tell what it is I''m looking at. Sorry', '2003-08-16 22:29:50.000000', NULL, 1),
(389989, 32854, 10686, '<td valign="top">This is a nice shot, I like the expression on the subject and the use of the rope in the composition. He does seem rather lonely, but I don''t get the feeling of desolation. He seems too content to be truly desolate.</td>', 'This is a nice shot, I like the expression on the subject and the use of the rope in the composition. He does seem rather lonely, but I don''t get the feeling of desolation. He seems too content to be truly desolate.', '2003-08-16 22:36:34.000000', NULL, 1),
(389990, 32407, 10686, '<td valign="top">I get the desolation in this shot and I like it, but somehow the composition is a bit strange. I wish the drawing that gives the picture its title were clearer.</td>', 'I get the desolation in this shot and I like it, but somehow the composition is a bit strange. I wish the drawing that gives the picture its title were clearer.', '2003-08-16 22:38:46.000000', NULL, 1),
(389991, 32588, 10686, '<td valign="top">I like it!</td>', 'I like it!', '2003-08-16 22:39:05.000000', NULL, 1),
(389992, 32344, 10686, '<td valign="top">This person seems truly desolate. Nice shot too</td>', 'This person seems truly desolate. Nice shot too', '2003-08-16 22:40:48.000000', NULL, 1),
(389993, 33098, 10686, '<td valign="top">An interesting juxtaposition of objects, but the figure in the picture with open arms seems welcoming and warm, which I really don''t associate with being desolate.</td>', 'An interesting juxtaposition of objects, but the figure in the picture with open arms seems welcoming and warm, which I really don''t associate with being desolate.', '2003-08-16 22:44:31.000000', NULL, 1),
(389994, 33166, 10686, '<td valign="top">I think I understand what this is trying to get at, but I wish the factory in the background (if that''s what it is) were a bit sharper than it is. Not in focus, but just enough so that I know for sure what it is. I love the colors and the overall composition.</td>', 'I think I understand what this is trying to get at, but I wish the factory in the background (if that''s what it is) were a bit sharper than it is. Not in focus, but just enough so that I know for sure what it is. I love the colors and the overall composition.', '2003-08-16 22:47:05.000000', NULL, 1),
(389995, 32516, 10686, '<td valign="top">Nice subject and I like the B&amp;W on this, I think it might be better composed if the skull was a bit smaller in the foreground and not so dominant.</td>', 'Nice subject and I like the B&W on this, I think it might be better composed if the skull was a bit smaller in the foreground and not so dominant.', '2003-08-16 22:50:39.000000', NULL, 1),
(389998, 33051, 10686, '<td valign="top">I see what this shot is getting at, but it is soft, and a bit flat. I Also think a wider shot that included more of the subject''s head and having him remove his tanktop to get rid of the distracting white parts would have improved this a lot.</td>', 'I see what this shot is getting at, but it is soft, and a bit flat. I Also think a wider shot that included more of the subject''s head and having him remove his tanktop to get rid of the distracting white parts would have improved this a lot.', '2003-08-16 22:53:49.000000', NULL, 1),
(389999, 33220, 10686, '<td valign="top">I love this</td>', 'I love this', '2003-08-16 22:54:25.000000', NULL, 1),
(390000, 32989, 10686, '<td valign="top">Great looking abandoned building, certainly is desolate.</td>', 'Great looking abandoned building, certainly is desolate.', '2003-08-16 22:58:14.000000', NULL, 1),
(390002, 32966, 10686, '<td valign="top">Certainly seems desolate, but the composition and the tonal range just aren''t there.</td>', 'Certainly seems desolate, but the composition and the tonal range just aren''t there.', '2003-08-16 22:59:31.000000', NULL, 1),
(390003, 33199, 10686, '<td valign="top">Interesting subject and it certainly is desolate, but the huge tree competes with the building too much. Maybe a wider shot would be better, or from another angle</td>', 'Interesting subject and it certainly is desolate, but the huge tree competes with the building too much. Maybe a wider shot would be better, or from another angle', '2003-08-16 23:01:17.000000', NULL, 1),
(390006, 33237, 11241, '<td valign="top">Love this B&amp;W Photo</td>', 'Love this B&W Photo', '2003-08-16 23:12:44.000000', NULL, 1),
(390007, 33109, 10686, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2003-08-16 23:15:24.000000', NULL, 1),
