(390046, 33238, 10341, '<td valign="top">no comment! :P</td>', 'no comment! :P', '2003-08-17 00:15:19.000000', NULL, 1),
(390050, 33231, 10686, '<td valign="top">This a a great shot, well lit and composed, but, I think that although, this situation could cause a child to feel desolate, if they didn''t get another cone, it just doesn''t convey a feeling of desolation to me</td>', 'This a a great shot, well lit and composed, but, I think that although, this situation could cause a child to feel desolate, if they didn''t get another cone, it just doesn''t convey a feeling of desolation to me', '2003-08-17 00:19:17.000000', NULL, 1),
(390067, 33227, 8377, '<td valign="top">I love this.. the halls, the shadows... the only thing is the light.  I feel it brings sort of an undesolation-feeling to the photo, but I do love it otherwise.  I like the angle that you shot it at also.</td>', 'I love this.. the halls, the shadows... the only thing is the light.  I feel it brings sort of an undesolation-feeling to the photo, but I do love it otherwise.  I like the angle that you shot it at also.', '2003-08-17 01:11:27.000000', NULL, 1),
(390068, 32656, 8377, '<td valign="top">Oooh, absolutely love the lighting!</td>', 'Oooh, absolutely love the lighting!', '2003-08-17 01:12:04.000000', NULL, 1),
(390070, 33198, 8377, '<td valign="top">I like the photo, and the sunset and crumbling house.  I like the cropping on this, but the photo looks a tad blurry, maybe its just that its getting dark and hard to see the ground.</td>', 'I like the photo, and the sunset and crumbling house.  I like the cropping on this, but the photo looks a tad blurry, maybe its just that its getting dark and hard to see the ground.', '2003-08-17 01:13:25.000000', NULL, 1),
