(390808, 33177, 9906, '<td valign="top">Wow.  I''m impressed that you could convey so much feeling in this one and you don''t even get to see the expression on the subjects face.  Wonderful textures and the colors help to set the mood.  Really nice!</td>', 'Wow.  I''m impressed that you could convey so much feeling in this one and you don''t even get to see the expression on the subjects face.  Wonderful textures and the colors help to set the mood.  Really nice!', '2003-08-17 22:26:28.000000', NULL, 1),
(390809, 33026, 5705, '<td valign="top">I like this alot-- Great lines-- makes you wonder if the train is around the bend?--9</td>', 'I like this alot-- Great lines-- makes you wonder if the train is around the bend?--9', '2003-08-17 22:26:37.000000', NULL, 1),
(390812, 32949, 5705, '<td valign="top">Has to be a top runner-- great image - 9</td>', 'Has to be a top runner-- great image - 9', '2003-08-17 22:29:48.000000', NULL, 1),
