(390826, 32656, 9906, '<td valign="top">Very simple but conveying the theme nicely.</td>', 'Very simple but conveying the theme nicely.', '2003-08-17 22:45:19.000000', NULL, 1),
(390827, 32928, 9906, '<td valign="top">Wery nice....What is it?  or what WAS it???</td>', 'Wery nice....What is it?  or what WAS it???', '2003-08-17 22:51:14.000000', NULL, 1),
(390830, 32958, 9906, '<td valign="top">Very cool.  Where is this???</td>', 'Very cool.  Where is this???', '2003-08-17 22:56:46.000000', NULL, 1),
(390831, 32800, 10145, '<td valign="top">The ant makes a nice addition to this...</td>', 'The ant makes a nice addition to this...', '2003-08-17 23:06:57.000000', NULL, 1),
(390833, 32814, 8377, '<td valign="top">Very creative!  Nice shot and cropping!</td>', 'Very creative!  Nice shot and cropping!', '2003-08-17 23:16:18.000000', NULL, 1),
(390853, 33107, 10402, '<td valign="top">I love merry-go-rounds and hope I''ll always be able to ride them. I can feel the yearning of this couple. I wish you had made the image a bit larger, and it seems a bit out of focus. But I like the composition here with the couple, facing away, at the side with most of the merry-go-round in the photo.</td>', 'I love merry-go-rounds and hope I''ll always be able to ride them. I can feel the yearning of this couple. I wish you had made the image a bit larger, and it seems a bit out of focus. But I like the composition here with the couple, facing away, at the side with most of the merry-go-round in the photo.', '2003-08-18 00:20:00.000000', NULL, 1),
(390854, 32344, 11096, '<td valign="top">There are so many shades and textures in this picture.  I love it.</td>', 'There are so many shades and textures in this picture.  I love it.', '2003-08-18 00:21:19.000000', NULL, 1),
(390855, 32818, 11096, '<td valign="top">This picture is not only a good crisp detailed picture but it meets the challenge well.</td>', 'This picture is not only a good crisp detailed picture but it meets the challenge well.', '2003-08-18 00:21:53.000000', NULL, 1),
(390856, 33042, 7778, '<td valign="top">&gt; 7</td>', '> 7', '2003-08-18 00:22:47.000000', NULL, 1),
(390857, 33048, 11096, '<td valign="top">I learned something from seeing this picture.  I like the way it is focused up close but the image in the background is what is "desolate''.  Thanks for the example.</td>', 'I learned something from seeing this picture.  I like the way it is focused up close but the image in the background is what is "desolate''.  Thanks for the example.', '2003-08-18 00:22:55.000000', NULL, 1),
(390858, 32947, 7969, '<td valign="top">I quite like your shot, I am not sure if it is on topic, but that is not so important to me.  It is my highest rated shot in this challenge so far.  You have certainly captured a very ''human'' moment. His forehead is slightly overexposed, but none the less excellent job.</td>', 'I quite like your shot, I am not sure if it is on topic, but that is not so important to me.  It is my highest rated shot in this challenge so far.  You have certainly captured a very ''human'' moment. His forehead is slightly overexposed, but none the less excellent job.', '2003-08-18 00:23:08.000000', NULL, 1),
(390859, 32407, 7969, '<td valign="top">This is one of the saddest shots I have seen.  And your title is poignant. I think it will likely be overlooked on dpc but it certainly has ''something''.  Good find.</td>', 'This is one of the saddest shots I have seen.  And your title is poignant. I think it will likely be overlooked on dpc but it certainly has ''something''.  Good find.', '2003-08-18 00:25:21.000000', NULL, 1),
(390860, 33078, 7778, '<td valign="top">Spectacular, eery shot with a strong personal appeal to my tastes. Love the dancing, foggy lights and the diffuse vanishing road...<br/> <br/>I commend the photographer for what I consider I daring submission within the context of this site! &gt; 6 by my scale, plus one extra point to encourage similarly ''different'' images (and to make up for those who will award a 1)  ;-)</td>', 'Spectacular, eery shot with a strong personal appeal to my tastes. Love the dancing, foggy lights and the diffuse vanishing road... I commend the photographer for what I consider I daring submission within the context of this site! > 6 by my scale, plus one extra point to encourage similarly ''different'' images (and to make up for those who will award a 1)  ;-)', '2003-08-18 00:34:47.000000', NULL, 1),
(390865, 32928, 9582, '<td valign="top">I like this very much. I am happy that you chose to show us something different. I''ve seen so many delapidated old buildings in this challenge and this one has the most eye appeal in my opinion.</td>', 'I like this very much. I am happy that you chose to show us something different. I''ve seen so many delapidated old buildings in this challenge and this one has the most eye appeal in my opinion.', '2003-08-18 00:43:08.000000', NULL, 1),
(390867, 32895, 9582, '<td valign="top">This is a great shot. It is very well composed and executed.</td>', 'This is a great shot. It is very well composed and executed.', '2003-08-18 00:44:28.000000', NULL, 1),
(390870, 33227, 9582, '<td valign="top">I like your use of light in this photo. Composition is very good too.</td>', 'I like your use of light in this photo. Composition is very good too.', '2003-08-18 00:47:29.000000', NULL, 1),
(390879, 32668, 6378, '<td valign="top">The sand is too white and unnatural. Looks like moist beach sand rather desert sand. Overall as good composition. Would have worked better if the sand was desert sand.</td>', 'The sand is too white and unnatural. Looks like moist beach sand rather desert sand. Overall as good composition. Would have worked better if the sand was desert sand.', '2003-08-18 00:55:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(390947, 33026, 11078, '<td valign="top">This person would have to be very desolute and rejected to sit and wait for a train.</td>', 'This person would have to be very desolute and rejected to sit and wait for a train.', '2003-08-18 01:26:24.000000', NULL, 1),
(390951, 32451, 11078, '<td valign="top">I think this is more like an oil painting</td>', 'I think this is more like an oil painting', '2003-08-18 01:27:28.000000', NULL, 1),
(391032, 33216, 10867, '<td valign="top">This is very interesting use of negative space.  (I know that''s not what this particular challenge is about, but this photo does happen to display effective use of negative space.)  The little house certainly looks isolated, but I''m not sure that it also looks desolate.</td>', 'This is very interesting use of negative space.  (I know that''s not what this particular challenge is about, but this photo does happen to display effective use of negative space.)  The little house certainly looks isolated, but I''m not sure that it also looks desolate.', '2003-08-18 01:46:31.000000', NULL, 1),
(391040, 33196, 10867, '<td valign="top">I like this composition a lot.  The empty pavement and the blown about bits of paper and the dead leaves do certainly coinvey a feeling of desolation to me.  Nice interpreation of the challenge.</td>', 'I like this composition a lot.  The empty pavement and the blown about bits of paper and the dead leaves do certainly coinvey a feeling of desolation to me.  Nice interpreation of the challenge.', '2003-08-18 01:48:40.000000', NULL, 1),
(391056, 33081, 10867, '<td valign="top">I love the image.  The tones are lovely and the use of the ruined arch as a frame for the part of the structure beyond it has worked very well.  I also love the uncut grass in the foreground and the pretty clouds in the sky.  To my eye, though, the bright sunlight and the light sky with pretty, wispy clouds play against the idea of desolation.  Nonetheless, I think that this is a beautiful image, and it could certainly be argued that the ruins and the uncut grass convey a sense of abandonment and desolation.</td>', 'I love the image.  The tones are lovely and the use of the ruined arch as a frame for the part of the structure beyond it has worked very well.  I also love the uncut grass in the foreground and the pretty clouds in the sky.  To my eye, though, the bright sunlight and the light sky with pretty, wispy clouds play against the idea of desolation.  Nonetheless, I think that this is a beautiful image, and it could certainly be argued that the ruins and the uncut grass convey a sense of abandonment and desolation.', '2003-08-18 01:53:30.000000', NULL, 1),
(391119, 33133, 11308, '<td valign="top">Very clever...</td>', 'Very clever...', '2003-08-18 02:59:19.000000', NULL, 1),
(391189, 32876, 3540, '<td valign="top">Even if this is on an upward slope, tilted horizons are probably the #2 worse thing you can do to a picture (out of focus being #1).  Looks like some interesting geometry.  If it were me I''d have chosen an alternate perspective.</td>', 'Even if this is on an upward slope, tilted horizons are probably the #2 worse thing you can do to a picture (out of focus being #1).  Looks like some interesting geometry.  If it were me I''d have chosen an alternate perspective.', '2003-08-18 05:52:44.000000', NULL, 1),
(391190, 33107, 3540, '<td valign="top">Rule #3 - Make your photograph as large as you possibly can.  This is the 3rd biggest culprit for pictures doing poorly (#1 is out of focus, #2 is tilted horizons).  The concept looks very good, its a shame about the size and the sunflare.</td>', 'Rule #3 - Make your photograph as large as you possibly can.  This is the 3rd biggest culprit for pictures doing poorly (#1 is out of focus, #2 is tilted horizons).  The concept looks very good, its a shame about the size and the sunflare.', '2003-08-18 05:54:45.000000', NULL, 1),
(391191, 32836, 3540, '<td valign="top">This one needs to portray a little more of the damage than this.  I can see where this one is trying to go (I think) and this just isn''t putting a picture of destruction in my head like it should be.</td>', 'This one needs to portray a little more of the damage than this.  I can see where this one is trying to go (I think) and this just isn''t putting a picture of destruction in my head like it should be.', '2003-08-18 05:56:22.000000', NULL, 1),
(391192, 33142, 3540, '<td valign="top">I''m not really sure how this one ties into the challenge.  The black border is way too much for this shot.  Probably altogether unnecessary to be perfectly honest.</td>', 'I''m not really sure how this one ties into the challenge.  The black border is way too much for this shot.  Probably altogether unnecessary to be perfectly honest.', '2003-08-18 05:59:04.000000', NULL, 1),
(391193, 33197, 3540, '<td valign="top">aside from being black and white, I don''t know what this has to do with the topic.  Looks like some nice scenery in the background.  This seems like a picture waiting for a subject waiting to wander in from one side of the picture.</td>', 'aside from being black and white, I don''t know what this has to do with the topic.  Looks like some nice scenery in the background.  This seems like a picture waiting for a subject waiting to wander in from one side of the picture.', '2003-08-18 06:01:08.000000', NULL, 1),
(391196, 33015, 3540, '<td valign="top">The horizon seems tilted a little down from left to right.   Picture is good and dreary, so I can appreciate the mood of this.  I think it meets the challenge, but a little loosely.  It might be just a little too dark.</td>', 'The horizon seems tilted a little down from left to right.   Picture is good and dreary, so I can appreciate the mood of this.  I think it meets the challenge, but a little loosely.  It might be just a little too dark.', '2003-08-18 06:04:30.000000', NULL, 1),
(391198, 32783, 3540, '<td valign="top">She looks a little too pretty to be a bum, but who knows?   Good expression on her face though one way or the other.</td>', 'She looks a little too pretty to be a bum, but who knows?   Good expression on her face though one way or the other.', '2003-08-18 06:06:06.000000', NULL, 1),
(391202, 33219, 3540, '<td valign="top">The idea is noble, but the execution just wasn''t there.  I wasn''t sure how many setup studio shots would be here.  I was guessing few.  This is the first one and overall I don''t think its terrible, but it does need to be in a little better focus.</td>', 'The idea is noble, but the execution just wasn''t there.  I wasn''t sure how many setup studio shots would be here.  I was guessing few.  This is the first one and overall I don''t think its terrible, but it does need to be in a little better focus.', '2003-08-18 06:07:51.000000', NULL, 1),
(391204, 32769, 3540, '<td valign="top">This is humorous, but I''m seeing this photo being near the bottom for this challenge.  It just doesn''t have any other real positive qualitites aside from being funny, but quite possibly, you were just out to give us a chuckle anyway.</td>', 'This is humorous, but I''m seeing this photo being near the bottom for this challenge.  It just doesn''t have any other real positive qualitites aside from being funny, but quite possibly, you were just out to give us a chuckle anyway.', '2003-08-18 06:09:35.000000', NULL, 1),
(391206, 32926, 3540, '<td valign="top">Hard to tell what really went on here.  Concentrating the picture on a smaller area would''ve been easier to tell.  From here, it looks like just a bunch of trees.  Without the title, its hard to tell much of anything.</td>', 'Hard to tell what really went on here.  Concentrating the picture on a smaller area would''ve been easier to tell.  From here, it looks like just a bunch of trees.  Without the title, its hard to tell much of anything.', '2003-08-18 06:11:44.000000', NULL, 1),
(391208, 33130, 3540, '<td valign="top">Best one so far at meeting the challenge.  Probably the one with the most potential too.  DOF is too shallow for this one.  Would''ve been a great negative space entry as well.</td>', 'Best one so far at meeting the challenge.  Probably the one with the most potential too.  DOF is too shallow for this one.  Would''ve been a great negative space entry as well.', '2003-08-18 06:13:17.000000', NULL, 1),
(391210, 32725, 3540, '<td valign="top">Looks like a fantastic place to go parking.  Quiet, secluded.  A high-schoolers dream spot.  The picture is just too dark, but it kind of has to be to get the effect.  Really as I think about it, its a great idea, but in print, it just doesn''t have the qualities I''m looking for, photographically.</td>', 'Looks like a fantastic place to go parking.  Quiet, secluded.  A high-schoolers dream spot.  The picture is just too dark, but it kind of has to be to get the effect.  Really as I think about it, its a great idea, but in print, it just doesn''t have the qualities I''m looking for, photographically.', '2003-08-18 06:17:20.000000', NULL, 1),
(391213, 32397, 3540, '<td valign="top">The lighting on this one is very bland and flat.  Looks almost like it was taken with too long of an exposure.   Maybe the flash was too bright.  At any rate, not a real high quality photo.  Not a great interpretation of this challenge, especially with the televisions still on.</td>', 'The lighting on this one is very bland and flat.  Looks almost like it was taken with too long of an exposure.   Maybe the flash was too bright.  At any rate, not a real high quality photo.  Not a great interpretation of this challenge, especially with the televisions still on.', '2003-08-18 06:19:42.000000', NULL, 1),
(391327, 33026, 11313, '<td valign="top">I like this photo, it''s like saying "What''s next ON  the path of Life".<br/></td>', 'I like this photo, it''s like saying "What''s next ON  the path of Life".', '2003-08-18 09:05:39.000000', NULL, 1),
(391329, 32760, 11314, '<td valign="top">I really like the composition of this shot.  I would have rated it higher if it were a little less bright.</td>', 'I really like the composition of this shot.  I would have rated it higher if it were a little less bright.', '2003-08-18 09:07:40.000000', NULL, 1),
(391337, 33045, 11314, '<td valign="top">Very eye-catching vibrant color.</td>', 'Very eye-catching vibrant color.', '2003-08-18 09:18:03.000000', NULL, 1),
(391341, 32668, 11314, '<td valign="top">It looks too contrived, but I like the idea expressed.</td>', 'It looks too contrived, but I like the idea expressed.', '2003-08-18 09:31:38.000000', NULL, 1),
(391343, 33151, 11304, '<td valign="top">This is excellent, though I wonder how much colorizing you had to use to get the two bands of darker blue with the lighter blue through the centre and around the branches.</td>', 'This is excellent, though I wonder how much colorizing you had to use to get the two bands of darker blue with the lighter blue through the centre and around the branches.', '2003-08-18 09:32:31.000000', NULL, 1),
(391349, 32699, 11314, '<td valign="top">This is a good representation of the topic, but I wonder if it would have been better if the skull hadn''t been sitting exactly upright like it was placed there.</td>', 'This is a good representation of the topic, but I wonder if it would have been better if the skull hadn''t been sitting exactly upright like it was placed there.', '2003-08-18 09:45:19.000000', NULL, 1),
(391355, 33065, 11314, '<td valign="top">I like the picure, but the title needs some work.  The title makes this "too cute by half."</td>', 'I like the picure, but the title needs some work.  The title makes this "too cute by half."', '2003-08-18 09:55:08.000000', NULL, 1),
(391384, 33179, 8891, '<td valign="top">while there is desolation here, the verdancy off sets it a bit too much</td>', 'while there is desolation here, the verdancy off sets it a bit too much', '2003-08-18 10:34:03.000000', NULL, 1),
(391386, 32887, 7994, '<td valign="top">is it b/w or you colored it in sepia?</td>', 'is it b/w or you colored it in sepia?', '2003-08-18 10:34:39.000000', NULL, 1),
(391387, 32606, 8891, '<td valign="top">is the street desolate or the child, could be either but I cannot tell from this.</td>', 'is the street desolate or the child, could be either but I cannot tell from this.', '2003-08-18 10:34:53.000000', NULL, 1),
(391388, 33105, 7994, '<td valign="top">very good feeling of desolation</td>', 'very good feeling of desolation', '2003-08-18 10:35:23.000000', NULL, 1),
(391390, 32922, 8891, '<td valign="top">great sky, but not the color you want to have to represents this, perhaps. might have been better in BW</td>', 'great sky, but not the color you want to have to represents this, perhaps. might have been better in BW', '2003-08-18 10:35:59.000000', NULL, 1),
(391391, 32802, 8891, '<td valign="top">great for right angles</td>', 'great for right angles', '2003-08-18 10:36:26.000000', NULL, 1),
(391393, 33230, 8891, '<td valign="top">just enough blue sky to knock it off the top, but other wise wonderful</td>', 'just enough blue sky to knock it off the top, but other wise wonderful', '2003-08-18 10:37:13.000000', NULL, 1),
(391400, 32825, 8891, '<td valign="top">super comp, nice choice of a desolated area to shot, the only thing holding me back here is that the model is looking too clean and neat.</td>', 'super comp, nice choice of a desolated area to shot, the only thing holding me back here is that the model is looking too clean and neat.', '2003-08-18 10:43:12.000000', NULL, 1),
(391402, 32947, 8891, '<td valign="top">I think the story is pretty much evident here.</td>', 'I think the story is pretty much evident here.', '2003-08-18 10:47:47.000000', NULL, 1),
(391405, 33045, 9338, '<td valign="top">I never realized that desolation can be so hauntingly beautiful.<br/></td>', 'I never realized that desolation can be so hauntingly beautiful.', '2003-08-18 10:49:58.000000', NULL, 1),
(391434, 33193, 9906, '<td valign="top">Really well put together.  I like how you maintained the color and still  achieved a sense of desolation.  The green foreground really offset the rust red of the truck (car?).  And the shadowy entrance behind it really give this a sense of perspective!</td>', 'Really well put together.  I like how you maintained the color and still  achieved a sense of desolation.  The green foreground really offset the rust red of the truck (car?).  And the shadowy entrance behind it really give this a sense of perspective!', '2003-08-18 11:07:19.000000', NULL, 1),
(391477, 32718, 4500, '<td valign="top">the color is wonderfull</td>', 'the color is wonderfull', '2003-08-18 11:28:07.000000', NULL, 1),
(391483, 32496, 11322, '<td valign="top">nice photo, great focus on the bees.....poor girl.</td>', 'nice photo, great focus on the bees.....poor girl.', '2003-08-18 11:34:41.000000', NULL, 1),
(391498, 33163, 11111, '<td valign="top">Very nice composition. It makes me feel like I''m there!</td>', 'Very nice composition. It makes me feel like I''m there!', '2003-08-18 11:47:38.000000', NULL, 1),
(391501, 33216, 7263, '<td valign="top">very clever ;) should ahve put soem little foot prints too</td>', 'very clever ;) should ahve put soem little foot prints too', '2003-08-18 11:48:39.000000', NULL, 1),
(391502, 32895, 9953, '<td valign="top">Nice look and feel.  Shades and angles are great...nice uphill effect.  Interesting facade feel wth the old items covered by new (is that a price tag? ;0 ) . Nice play-on-Dylan.  This should make your mama proud.<br/>Prof. M.</td>', 'Nice look and feel.  Shades and angles are great...nice uphill effect.  Interesting facade feel wth the old items covered by new (is that a price tag? ;0 ) . Nice play-on-Dylan.  This should make your mama proud.Prof. M.', '2003-08-18 11:48:49.000000', NULL, 1),
(391517, 32797, 2223, '<td valign="top">Totally awesome!! Thought she was real at first glace, the face looks so life-like, great shot!</td>', 'Totally awesome!! Thought she was real at first glace, the face looks so life-like, great shot!', '2003-08-18 12:01:16.000000', NULL, 1),
(391521, 32699, 2223, '<td valign="top">Beautiful colors, i love the angle of the background. Nicely done.</td>', 'Beautiful colors, i love the angle of the background. Nicely done.', '2003-08-18 12:05:55.000000', NULL, 1),
(391541, 32773, 6597, '<td valign="top">great composition      8</td>', 'great composition      8', '2003-08-18 12:20:10.000000', NULL, 1),
(391593, 33109, 11324, '<td valign="top">Excellent use of light. Good choice in using black and white vs. color.  Bravo!</td>', 'Excellent use of light. Good choice in using black and white vs. color.  Bravo!', '2003-08-18 12:55:12.000000', NULL, 1),
(391596, 33186, 11324, '<td valign="top">Wonderful contrast.  I don''t see the theme much here, though.  It looks to me as more of an "abandoned" theme, but it''s still a great photo!</td>', 'Wonderful contrast.  I don''t see the theme much here, though.  It looks to me as more of an "abandoned" theme, but it''s still a great photo!', '2003-08-18 12:56:29.000000', NULL, 1),
(391597, 33017, 4615, '<td valign="top">too spectacular to convey desolation</td>', 'too spectacular to convey desolation', '2003-08-18 12:57:29.000000', NULL, 1),
(391599, 33082, 4615, '<td valign="top">true.</td>', 'true.', '2003-08-18 12:57:52.000000', NULL, 1),
(391603, 33245, 11324, '<td valign="top">I like the human aspect of this.  Age.  Wisdom.  But it really has little to do with desolation.  I can feel it, but I don''t see it.  Perhaps a different title would have guided me towards your intention.  Nice photo, though.</td>', 'I like the human aspect of this.  Age.  Wisdom.  But it really has little to do with desolation.  I can feel it, but I don''t see it.  Perhaps a different title would have guided me towards your intention.  Nice photo, though.', '2003-08-18 12:59:32.000000', NULL, 1),
(391638, 33238, 4615, '<td valign="top">they''ve moved to somewhere better, so the implication is improvement, hope etc, <br/>not desolation?</td>', 'they''ve moved to somewhere better, so the implication is improvement, hope etc, not desolation?', '2003-08-18 13:46:13.000000', NULL, 1),
(391768, 33041, 9136, '<td valign="top">My favorite this week. Great idea, nice photo. 10.</td>', 'My favorite this week. Great idea, nice photo. 10.', '2003-08-18 15:57:01.000000', NULL, 1),
(391769, 33017, 9136, '<td valign="top">This is a really powerful picture - the colors in the sky are amazing. 9.</td>', 'This is a really powerful picture - the colors in the sky are amazing. 9.', '2003-08-18 15:57:47.000000', NULL, 1),
(391771, 33077, 9136, '<td valign="top">Nice picture, clear, strong, and fits the challenge. 9.</td>', 'Nice picture, clear, strong, and fits the challenge. 9.', '2003-08-18 15:58:15.000000', NULL, 1),
