(391882, 33111, 10686, '<td valign="top">Nice subject, maybe a wider shot would help. I find the border distracting.</td>', 'Nice subject, maybe a wider shot would help. I find the border distracting.', '2003-08-18 16:18:51.000000', NULL, 1),
(391907, 33172, 10686, '<td valign="top">I get the idea, but there''s too much happening visually in the picture to communicate it clearly. Maybe if one of the fallen trees dominated the frame.</td>', 'I get the idea, but there''s too much happening visually in the picture to communicate it clearly. Maybe if one of the fallen trees dominated the frame.', '2003-08-18 16:22:08.000000', NULL, 1),
