(392331, 33239, 7504, '<td valign="top">Cool.  Looks hot and desolate, Nice job.</td>', 'Cool.  Looks hot and desolate, Nice job.', '2003-08-18 23:19:47.000000', NULL, 1),
(392333, 33151, 7504, '<td valign="top">Ooh, I like this a lot.  The deep blue is very compelling, and the starkness of the branch.  Very nice!</td>', 'Ooh, I like this a lot.  The deep blue is very compelling, and the starkness of the branch.  Very nice!', '2003-08-18 23:20:15.000000', NULL, 1),
