(392339, 33210, 7504, '<td valign="top">This seems slightly over -sharpened to me, I like the composition and the choice of B/W very much.</td>', 'This seems slightly over -sharpened to me, I like the composition and the choice of B/W very much.', '2003-08-18 23:21:51.000000', NULL, 1),
(392341, 32943, 7504, '<td valign="top">This shot inspires me more than gives me a feeling of desolation.  It''s a very lovely sky.</td>', 'This shot inspires me more than gives me a feeling of desolation.  It''s a very lovely sky.', '2003-08-18 23:22:40.000000', NULL, 1),
