(392354, 33132, 7504, '<td valign="top">I wish this was sized bigger, it''s very effective otherwise.</td>', 'I wish this was sized bigger, it''s very effective otherwise.', '2003-08-18 23:25:14.000000', NULL, 1),
(392359, 33005, 7504, '<td valign="top">There''s something very compelling about this shot.  The love of a loyal friend, although his life may seem desolate, there''s joy here too.  Nice work.</td>', 'There''s something very compelling about this shot.  The love of a loyal friend, although his life may seem desolate, there''s joy here too.  Nice work.', '2003-08-18 23:28:57.000000', NULL, 1),
