INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(392362, 32797, 7504, '<td valign="top">This creeped me out at first, I really like it though, interesting and striking!</td>', 'This creeped me out at first, I really like it though, interesting and striking!', '2003-08-18 23:32:11.000000', NULL, 1),
(392365, 33194, 7504, '<td valign="top">This is my favorite of the "old house" shots.  I like your choice of titles.  I think I might like it a bit better in sepia, but this is my favorite of your shots so far! 9</td>', 'This is my favorite of the "old house" shots.  I like your choice of titles.  I think I might like it a bit better in sepia, but this is my favorite of your shots so far! 9', '2003-08-18 23:35:37.000000', NULL, 1),
(392368, 32451, 2817, '<td valign="top">It would really have been a good photograph, but the thing in the corner is very distracting from the beauty of the landscape. I couldn''t really figure out why you might put that there on purpose. I wish some of the objects such as the trees to be more clear. I love the hills.</td>', 'It would really have been a good photograph, but the thing in the corner is very distracting from the beauty of the landscape. I couldn''t really figure out why you might put that there on purpose. I wish some of the objects such as the trees to be more clear. I love the hills.', '2003-08-18 23:38:34.000000', NULL, 1),
(392372, 32819, 2817, '<td valign="top">I really love this photo, probably because of how much I like castles. But that is not really the only reason I like it. It is cool how the ruins sort of are in a haze in the background it really adds to desolate feel. Thanks for giving it a nice straightforward name.</td>', 'I really love this photo, probably because of how much I like castles. But that is not really the only reason I like it. It is cool how the ruins sort of are in a haze in the background it really adds to desolate feel. Thanks for giving it a nice straightforward name.', '2003-08-18 23:41:33.000000', NULL, 1),
(392375, 33017, 2817, '<td valign="top">The colors and the contrast here are what makes me give it a ten. The solid black against the colors really is wonderful.</td>', 'The colors and the contrast here are what makes me give it a ten. The solid black against the colors really is wonderful.', '2003-08-18 23:43:31.000000', NULL, 1),
(392377, 33045, 2817, '<td valign="top">Even though this picture is clearly not in a tropical area the first time I looked at it the colors reminded me of the bahamas or another carribean area. The sunlight that encompasses the tree really makes this picture magnificent. I especially like the two colors of the clouds. Although I guess you can take credit for that!</td>', 'Even though this picture is clearly not in a tropical area the first time I looked at it the colors reminded me of the bahamas or another carribean area. The sunlight that encompasses the tree really makes this picture magnificent. I especially like the two colors of the clouds. Although I guess you can take credit for that!', '2003-08-18 23:46:43.000000', NULL, 1),
(392381, 33107, 2567, '<td valign="top">I think this shot would be better if you had focused in more on the people in the wheelchairs and not included the whole merry go round. just part of it.  Also a larger size would have helped.</td>', 'I think this shot would be better if you had focused in more on the people in the wheelchairs and not included the whole merry go round. just part of it.  Also a larger size would have helped.', '2003-08-18 23:51:35.000000', NULL, 1),
(392382, 33078, 2567, '<td valign="top">Sorry but IMO this is just a blur.</td>', 'Sorry but IMO this is just a blur.', '2003-08-18 23:52:15.000000', NULL, 1),
(392384, 33205, 2567, '<td valign="top">This is a real push to meet the challenge IMO.  Interesting shot though.</td>', 'This is a real push to meet the challenge IMO.  Interesting shot though.', '2003-08-18 23:55:11.000000', NULL, 1),
(392407, 33232, 6325, '<td valign="top">Kudzu will take over the South.</td>', 'Kudzu will take over the South.', '2003-08-19 00:59:35.000000', NULL, 1),
(392413, 32783, 11078, '<td valign="top">whilst it looks a desolate place she looks quite well cared for  and I think its just a pose with a model</td>', 'whilst it looks a desolate place she looks quite well cared for  and I think its just a pose with a model', '2003-08-19 01:18:56.000000', NULL, 1),
(392414, 33102, 11078, '<td valign="top">A horrible place to be it looks so cold and baron</td>', 'A horrible place to be it looks so cold and baron', '2003-08-19 01:19:43.000000', NULL, 1),
(392416, 32671, 11078, '<td valign="top">A bit bleak I hope its not the future</td>', 'A bit bleak I hope its not the future', '2003-08-19 01:21:05.000000', NULL, 1),
(392417, 32818, 11078, '<td valign="top">Its certainly seen the last of its travels</td>', 'Its certainly seen the last of its travels', '2003-08-19 01:22:00.000000', NULL, 1),
(392418, 33101, 11078, '<td valign="top">very spooky</td>', 'very spooky', '2003-08-19 01:22:47.000000', NULL, 1),
(392419, 32607, 11078, '<td valign="top">oh for the peace!</td>', 'oh for the peace!', '2003-08-19 01:23:27.000000', NULL, 1),
(392421, 33051, 5822, '<td valign="top">I like the shadow and the expression on the subjects face is effective,  but find the soft focus for this much of a close up to be distracting. In addition,  I think I would have liked different lighting, maybe a darker key...this is just too bright.</td>', 'I like the shadow and the expression on the subjects face is effective,  but find the soft focus for this much of a close up to be distracting. In addition,  I think I would have liked different lighting, maybe a darker key...this is just too bright.', '2003-08-19 01:35:10.000000', NULL, 1),
(392429, 33111, 11078, '<td valign="top">This looks like the photo that windows has in thier screensavers The shack looks as if its about to fall down and could be teeming with wild life</td>', 'This looks like the photo that windows has in thier screensavers The shack looks as if its about to fall down and could be teeming with wild life', '2003-08-19 01:42:37.000000', NULL, 1),
(392432, 32752, 5822, '<td valign="top">I like the composition, although I''m not sure it says desloation to me.  I do, however, find your lighting to be way too harsh as it obscures the main subject, the sewing machine, with  glare to it''s body, which blocks interesting detail, as well as, the shadow cast on the background, which confuses it''s shape.  I don''t see any evidence that this machine has not been used in a while, unless your intention was to achieve that effect with the high grain image you''ve acheived.</td>', 'I like the composition, although I''m not sure it says desloation to me.  I do, however, find your lighting to be way too harsh as it obscures the main subject, the sewing machine, with  glare to it''s body, which blocks interesting detail, as well as, the shadow cast on the background, which confuses it''s shape.  I don''t see any evidence that this machine has not been used in a while, unless your intention was to achieve that effect with the high grain image you''ve acheived.', '2003-08-19 01:46:46.000000', NULL, 1),
