(392624, 33048, 11314, '<td valign="top">I like the focus on the chain instead of the child.  It enhances the idea of loneliness.</td>', 'I like the focus on the chain instead of the child.  It enhances the idea of loneliness.', '2003-08-19 09:45:13.000000', NULL, 1),
(392627, 32819, 11314, '<td valign="top">This is well done.</td>', 'This is well done.', '2003-08-19 09:47:09.000000', NULL, 1),
