(393317, 33053, 200, '<td valign="top">impressive shot</td>', 'impressive shot', '2003-08-20 00:24:54.000000', NULL, 1),
(393320, 33072, 9232, '<td valign="top">Good idea and the model seems to have produced something you could work with but I think the effect around the eyes is overdone.  The light on the model''s left arm (right of photo) is too hot; especially against the dark hair.  - 5</td>', 'Good idea and the model seems to have produced something you could work with but I think the effect around the eyes is overdone.  The light on the model''s left arm (right of photo) is too hot; especially against the dark hair.  - 5', '2003-08-20 00:26:38.000000', NULL, 1),
